/**
 * A write sent in place by the Workbench router (a page-data POST) is acknowledged by the write servlet itself: a
 * {@code 200} page answer with an {@code X-Workbench-Write: done} header and an {@code end} record whose metadata says
 * so, instead of a redirect that cannot be told apart from a redirect of a gateway or login proxy. Other clients keep
 * the redirect to the Summary page.
 */
class InPlaceWriteSuccessTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	@TempDir
	static Path tempDir;

	private Repository repository;

	private ValueFactory vf;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		vf = repository.getValueFactory();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createLiteral("o"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	static Stream<Arguments> writes() throws Exception {
		Path data = tempDir.resolve("data.ttl");
		Files.writeString(data, "<urn:added> <urn:p> \"added\" .", StandardCharsets.UTF_8);
		return Stream.of(
				Arguments.of("add", (Supplier<TransformationServlet>) AddServlet::new,
						(Consumer<MockHttpServletRequest>) request -> {
							request.addParameter("url", data.toUri().toString());
							request.addParameter("Content-Type", "text/turtle");
						}),
				Arguments.of("update", (Supplier<TransformationServlet>) UpdateServlet::new,
						(Consumer<MockHttpServletRequest>) request -> request.addParameter("update",
								"INSERT DATA { <urn:added> <urn:p> \"added\" }")),
				Arguments.of("clear", (Supplier<TransformationServlet>) ClearServlet::new,
						(Consumer<MockHttpServletRequest>) request -> {
						}),
				Arguments.of("remove", (Supplier<TransformationServlet>) RemoveServlet::new,
						(Consumer<MockHttpServletRequest>) request -> request.addParameter("subj", "<urn:s>")));
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("writes")
	void anInPlaceWriteIsAcknowledgedByAPageAnswerInsteadOfARedirect(String view,
			Supplier<TransformationServlet> servlet, Consumer<MockHttpServletRequest> parameters) throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/repositories/test/" + view);
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		parameters.accept(request);
		MockHttpServletResponse response = run(servlet.get(), view, request);

		assertThat(response.getRedirectedUrl()).as("no redirect for a page-data write").isNull();
		assertThat(response.getStatus()).isEqualTo(200);
		assertThat(response.getContentType()).isEqualTo(WorkbenchPageProtocol.CONTENT_TYPE);
		assertThat(response.getHeader("X-Workbench-Write")).isEqualTo("done");
		assertThat(response.getHeader("Cache-Control")).isEqualTo("no-cache, no-store");
		List<JsonNode> records = response.getContentAsString()
				.lines()
				.filter(line -> !line.isBlank())
				.map(JSON_MAPPER::readTree)
				.toList();
		assertThat(records).extracting(record -> record.path("type").asText())
				.containsExactly("head", "view", "end");
		assertThat(records.get(1).path("id").asText()).isEqualTo(view);
		JsonNode metadata = records.get(2).path("metadata");
		assertThat(metadata.path("workbench-write").asText()).isEqualTo("done");
		assertThat(metadata.path("workbench-write-location").asText()).isEqualTo("summary");
		assertWritten(view);
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("writes")
	void otherClientsKeepTheRedirectToTheSummary(String view, Supplier<TransformationServlet> servlet,
			Consumer<MockHttpServletRequest> parameters) throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/repositories/test/" + view);
		parameters.accept(request);
		MockHttpServletResponse response = run(servlet.get(), view, request);

		assertThat(response.getRedirectedUrl()).isEqualTo("summary");
		assertThat(response.getHeader("X-Workbench-Write")).isNull();
		assertWritten(view);
	}

	private void assertWritten(String view) {
		IRI s = vf.createIRI("urn:s");
		try (RepositoryConnection connection = repository.getConnection()) {
			switch (view) {
			case "add", "update" -> assertThat(connection.hasStatement(vf.createIRI("urn:added"), null, null, false))
					.isTrue();
			case "clear" -> assertThat(connection.isEmpty()).isTrue();
			case "remove" -> assertThat(connection.hasStatement(s, null, null, false)).isFalse();
			default -> throw new IllegalArgumentException(view);
			}
		}
	}

	private MockHttpServletResponse run(TransformationServlet servlet, String name, MockHttpServletRequest request)
			throws Exception {
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams(name, "cookie-max-age", "300"));
		try {
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response;
		} finally {
			servlet.destroy();
		}
	}
}
